program seven_plus_five {
    place x as ram_flowing at (0, 0) {
        in: w
        out: e
    }
    place y as ram_flowing at (1, 1) {
        in: s
        out: n
    }
    place add as adder at (0, 1) {
        in_a: w
        in_b: s
        out: e
    }
    place sink as ram_flowing at (0, 2) {
        in: w
        out: e
    }
}

